package com.johnny.hotel.settlement;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import com.johnny.hotel.settlement.SettlementRequests.*;import jakarta.validation.Valid;import lombok.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/finance/settlements")@RequiredArgsConstructor@PreAuthorize("hasAnyRole('FINANCE','OWNER','SUPER_ADMIN')")public class SettlementController{private final SettlementService service;@PostMapping public Result<SettlementView>importBatch(@Valid@RequestBody Import r){return Result.success(service.importBatch(r));}@PostMapping("/{id}/reconcile")public Result<SettlementView>reconcile(@PathVariable Long id,@Valid@RequestBody Reconcile r){return Result.success(service.reconcile(id,r));}@PostMapping("/{id}/payouts")public Result<GatewayPayout>payout(@PathVariable Long id,@Valid@RequestBody Payout r){return Result.success(service.payout(id,r));}@GetMapping("/{id}")public Result<SettlementView>get(@PathVariable Long id){return Result.success(service.get(id));}@GetMapping public Result<PageResult<SettlementBatch>>list(@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(service.list(page,pageSize));}@GetMapping("/metrics")public Result<SettlementMetrics>metrics(){return Result.success(service.metrics());}}
